function esc(value = "") { return String(value).replace(/[&<>"']/g, char => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;" }[char])); }
function messageOf(error) { return error instanceof Error ? error.message : "حدث خطأ غير متوقع"; }
function toast(message) { const element = document.createElement("div"); element.className = "toast"; element.textContent = message; document.body.append(element); window.setTimeout(() => element.remove(), 3200); }
function fmtDate(value) { return value ? new Date(value).toLocaleString("ar-SA", { dateStyle: "medium", timeStyle: "short" }) : "—"; }
async function query(procedure, input = undefined) { const suffix = input === undefined ? "" : `?input=${encodeURIComponent(JSON.stringify({ json: input }))}`; let response; try { response = await fetch(`/api/trpc/${procedure}${suffix}`, { credentials: "same-origin", cache: "no-store" }); } catch { throw new Error("تعذر الاتصال بالخادم. تحقّق من الشبكة ثم أعد المحاولة."); } const payload = await response.json().catch(() => null); if (!response.ok) throw new Error(payload?.error?.json?.message || "تعذر الاتصال بالخادم"); return payload?.result?.data?.json ?? payload?.result?.data; }
async function mutate(procedure, input) { let response; try { response = await fetch(`/api/trpc/${procedure}`, { method: "POST", credentials: "same-origin", cache: "no-store", headers: { "content-type": "application/json" }, body: JSON.stringify({ json: input }) }); } catch { throw new Error("تعذر الاتصال بالخادم. لم تُفقد إعداداتك؛ تحقّق من الشبكة ثم أعد المحاولة."); } const payload = await response.json().catch(() => null); if (!response.ok) throw new Error(payload?.error?.json?.message || "تعذر حفظ التعديلات"); return payload?.result?.data?.json ?? payload?.result?.data; }
function collection(key) { return state.collections.find(item => item.collectionKey === key); }
function content(key) { try { return JSON.parse(collection(key)?.content || "null"); } catch { return null; } }
function labelForItem(item, index) { return item?.title || item?.name || item?.question || `عنصر ${index + 1}`; }
function defaultItem(key) { const order = Array.isArray(content(key)) ? content(key).length : 0; const base = { sortOrder: order, isVisible: true }; if (key === "services") return { ...base, emoji: "📚", title: "خدمة جديدة", items: ["خدمة فرعية جديدة"] }; if (key === "plans") return { ...base, emoji: "📦", title: "باقة جديدة", duration: "", features: ["ميزة جديدة"], popular: false, color: "blue" }; if (key === "downloads") return { ...base, categoryOrder: order, emoji: "📥", title: "فئة جديدة", items: [{ name: "ملف جديد", remoteFile: "", sortOrder: 0, isVisible: true }] }; if (key === "articles") return { ...base, title: "مقال جديد", category: "عام", publishedText: "", summary: "", body: "" }; if (key === "reviews") return { ...base, name: "اسم الطالب", university: "", body: "", rating: 5 }; if (key === "partners") return { ...base, name: "جهة تعليمية جديدة", kind: "جهة تعليمية" }; return { ...base, question: "سؤال جديد", answer: "الإجابة" }; }
function sanitizeSettings(data) { const next = { metaTitle: "واجبات بلس | خدمات أكاديمية سعودية", metaDescription: "خدمات أكاديمية موثوقة للطلاب الجامعيين في السعودية.", ...(data || {}) }; delete next.heroVoiceText; delete next.serviceVoiceTemplate; return next; }
function statusOptions(current, allowed) { return allowed.map(value => `<option value="${value}" ${current === value ? "selected" : ""}>${statuses[value]}</option>`).join(""); }

function loginDefaults() { return { template: "professional", backgroundStyle: "gradient", backgroundColor: "#f4f7ff", backgroundGradient: "linear-gradient(135deg, #eef3ff 0%, #f9fbff 48%, #e8faf5 100%)", cardStyle: "standard", cardColor: "#ffffff", cardOpacity: 94, cardBorderColor: "#ffffff", cardBorderWidth: 1, cardRadius: 28, cardBlur: 0, cardWidth: 430, fieldStyle: "modern", fieldColor: "#ffffff", fieldTextColor: "#15213d", fieldPlaceholderColor: "#77829a", fieldBorderColor: "#dce2f1", fieldBorderWidth: 1, fieldRadius: 14, fieldFontSize: 15, fontFamily: "Cairo", contentOrder: "logo,title,description,email,password,passkey,submit,footer", buttonStyle: "gradient", buttonColor: "#4966d6", buttonTextColor: "#ffffff", buttonRadius: 14, buttonGlow: 0, buttonAnimation: "none", logoSize: 64, logoPosition: "top", logoShape: "rounded", logoBorderColor: "#ffffff", logoBorderWidth: 0, logoGlow: 0, logoAnimation: "none", ownerPhotoSize: 0, ownerPhotoShape: "circle", entranceAnimation: "fade", animationDuration: 240, title: "مرحبًا بك في لوحة الإدارة", description: "دخول خاص ومؤمّن لإدارة الموقع وطلبات العملاء.", loginButtonText: "تسجيل الدخول", passkeyButtonText: "الدخول بالبصمة أو Passkey", footerText: "مساحة خاصة بمالك واجبات بلس", invalidCredentialsText: "بيانات الدخول غير صحيحة" }; }
function loginVisual(settings) { const value = { ...loginDefaults(), ...(settings || {}) }; const background = value.backgroundStyle === "image" && value.backgroundImageUrl ? `url('${esc(value.backgroundImageUrl)}') center/cover` : value.backgroundStyle === "solid" ? value.backgroundColor : (value.backgroundGradient || value.backgroundColor); return `--login-bg:${background};--login-card:${value.cardColor};--login-card-opacity:${Number(value.cardOpacity) / 100};--login-card-border:${value.cardBorderWidth}px solid ${value.cardBorderColor};--login-card-radius:${value.cardRadius}px;--login-card-width:${value.cardWidth}px;--login-card-blur:${value.cardBlur}px;--login-field:${value.fieldColor};--login-field-text:${value.fieldTextColor};--login-field-placeholder:${value.fieldPlaceholderColor};--login-field-border:${value.fieldBorderWidth}px solid ${value.fieldBorderColor};--login-field-radius:${value.fieldRadius}px;--login-font-size:${value.fieldFontSize}px;--login-button:${value.buttonColor};--login-button-text:${value.buttonTextColor};--login-button-radius:${value.buttonRadius}px;--login-button-glow:${value.buttonGlow}px;--login-logo-size:${value.logoSize}px;--login-logo-border:${value.logoBorderWidth}px solid ${value.logoBorderColor};--login-logo-glow:${value.logoGlow}px;--login-font:'${esc(value.fontFamily)}',Arial,sans-serif;--login-duration:${value.animationDuration}ms;`; }
function loginView() { const value = { ...loginDefaults(), ...(state.loginSettings || {}) }; const pieces = { logo: value.logoUrl ? `<img class="owner-login-logo logo-${value.logoShape}" src="${esc(value.logoUrl)}" alt="شعار الدخول" />` : `<div class="brand-dot">و</div>`, title: `<h1>${esc(value.title)}</h1>`, description: `<p>${esc(value.description)}</p>`, email: `<div class="field"><label>البريد الإلكتروني</label><input name="email" type="text" inputmode="email" required autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" dir="ltr" /></div>`, password: `<div class="field"><label>كلمة المرور</label><input name="password" type="password" required autocomplete="current-password" dir="ltr" /></div>`, passkey: window.PublicKeyCredential ? `<button class="btn btn-outline owner-passkey-login" type="button" data-login-passkey>${esc(value.passkeyButtonText)}</button>` : "", submit: `<button class="btn owner-login-submit" type="submit">${esc(value.loginButtonText)}</button>`, footer: `<small class="owner-login-footer">${esc(value.footerText)}</small>` }; const order = String(value.contentOrder || loginDefaults().contentOrder).split(","); return `<main class="login-view login-template-${esc(value.template)}" style="${loginVisual(value)}"><form id="login-form" class="login-card login-card-${esc(value.cardStyle)}" novalidate>${value.ownerPhotoUrl && Number(value.ownerPhotoSize) > 0 ? `<img class="owner-login-photo photo-${esc(value.ownerPhotoShape)}" src="${esc(value.ownerPhotoUrl)}" alt="صورة المالك" style="width:${Number(value.ownerPhotoSize)}px;height:${Number(value.ownerPhotoSize)}px" />` : ""}<div class="login-elements">${order.map(key => pieces[key] || "").join("")}</div><div id="login-error" class="error"></div></form></main>`; }
function navCount(key) { if (key === "requests") return state.stats?.requests || 0; if (key === "messages") return state.stats?.messages || 0; if (key === "submittedReviews") return state.stats?.pendingReviews || 0; if (key === "gallery") return state.media.length; if (["dashboard", "analytics", "ownerLogin", "siteSettings", "account", "design", "contact", "about"].includes(key)) return ""; return Array.isArray(content(key)) ? content(key).length : ""; }
function sidebar() { return `<aside class="sidebar"><div class="side-brand"><div class="brand-dot">و</div><div><b>واجبات بلس</b><br><span>مساحة إدارة المالك</span></div><button class="sidebar-close" data-sidebar-toggle aria-label="إغلاق القائمة">×</button></div><nav class="side-menu">${navSections.map(section => `<div class="nav-group"><p class="nav-group-title">${section.title}</p>${section.items.map(key => { const [icon, title] = labels[key]; const navAttribute = key === "visitorLinks" ? "data-visitor-links-nav" : key === "downloads" ? "data-downloads-nav" : `data-select="${key}"`; return `<button ${navAttribute} class="${state.selected === key ? "active" : ""}" aria-current="${state.selected === key ? "page" : "false"}"><span class="nav-item-icon">${icon}</span><span>${title}</span>${navCount(key) !== "" ? `<span class="count">${navCount(key)}</span>` : ""}</button>`; }).join("")}</div>`).join("")}</nav><div class="side-bottom"><span class="connection-dot"></span><div><b>الحفظ متصل بقاعدة البيانات</b><br><small>لوحة خاصة لا تظهر للزوار</small></div></div></aside>`; }
function statsCards() { const s = state.stats || {}; const services = Array.isArray(content("services")) ? content("services") : []; const downloads = Array.isArray(content("downloads")) ? content("downloads") : []; const cards = [["visits", "◎", "إجمالي الزيارات", s.visits, "المتابعة الإدارية"], ["requests", "▣", "طلبات تسليم الواجب", s.requests, "تحتاج المتابعة"], ["content", "📚", "الخدمات الرئيسية", services.length, "محتوى ظاهر أو مخفي"], ["content", "⊞", "الخدمات الفرعية", services.reduce((sum, item) => sum + (item.items || []).length, 0), "ضمن الخدمات"], ["content", "📥", "ملفات التحميل", downloads.reduce((sum, item) => sum + (item.items || []).length, 0), "المكتبة والفئات"], ["content", "📝", "المقالات", Array.isArray(content("articles")) ? content("articles").length : 0, "المدونة"], ["reviews", "★", "آراء الطلاب", Array.isArray(content("reviews")) ? content("reviews").length : 0, "العناصر المنشورة"], ["messages", "✉", "رسائل غير مقروءة", s.messages, "صندوق التواصل"], ["content", "⌘", "الجامعات", Array.isArray(content("universities")) ? content("universities").length : 0, "الجهات التعليمية"], ["content", "🏛", "شركاء النجاح", Array.isArray(content("partners")) ? content("partners").length : 0, "الجهات المرتبطة"]]; return `<section class="stat-grid">${cards.map(([tone, icon, label, value, hint]) => `<article class="stat-card stat-${tone}"><div class="stat-icon">${icon}</div><div><span>${label}</span><b>${Number(value || 0).toLocaleString("ar-SA")}</b><small>${hint}</small></div></article>`).join("")}</section>`; }
function analyticsPanel(stats) { const daily = Array.isArray(stats.dailyVisits) ? stats.dailyVisits : []; const sources = Array.isArray(stats.trafficSources) ? stats.trafficSources : []; const devices = Array.isArray(stats.deviceTypes) ? stats.deviceTypes : []; const requestStates = Array.isArray(stats.requestStatuses) ? stats.requestStatuses : []; const maxDaily = Math.max(1, ...daily.map(row => Number(row.count || 0))); const totalDeviceVisits = Math.max(1, devices.reduce((sum, row) => sum + Number(row.count || 0), 0)); const bars = daily.length ? daily.map(row => `<div class="analytics-bar"><span>${esc(String(row.date))}</span><i><b style="width:${Math.max(3, Math.round(Number(row.count || 0) / maxDaily * 100))}%"></b></i><strong>${Number(row.count || 0)}</strong></div>`).join("") : `<div class="empty">ستظهر حركة الزيارات هنا بعد استقبال زيارات فعلية.</div>`; const listRows = (rows, formatter = row => row.path) => rows.length ? rows.map(row => `<li><span>${esc(String(formatter(row) || "غير محدد"))}</span><b>${Number(row.count || 0)}</b></li>`).join("") : `<li><span>لا توجد بيانات كافية بعد</span></li>`; const sourceRows = listRows(sources, row => row.source || "direct"); const deviceRows = devices.length ? devices.map(row => `<li><span>${esc(row.deviceType || "desktop")}</span><b>${Math.round(Number(row.count || 0) / totalDeviceVisits * 100)}%</b></li>`).join("") : `<li><span>لا توجد بيانات بعد</span></li>`; const requestRows = listRows(requestStates, row => statuses[row.status] || row.status); const serviceRows = listRows(Array.isArray(stats.topServices) ? stats.topServices : [], row => String(row.path || "").replace("/services/", "خدمة رقم ")); const articleRows = listRows(Array.isArray(stats.topArticles) ? stats.topArticles : [], row => String(row.path || "").replace("/blog/articles/", "مقال رقم ")); const downloadRows = listRows(Array.isArray(stats.topDownloads) ? stats.topDownloads : [], row => decodeURIComponent(String(row.path || "").replace("/downloads/files/", ""))); return `<section class="analytics-metrics"><article><span>زوار اليوم</span><b>${Number(stats.visitsToday || 0).toLocaleString("ar-SA")}</b></article><article><span>زوار الأسبوع</span><b>${Number(stats.visitsWeek || 0).toLocaleString("ar-SA")}</b></article><article><span>زوار الشهر</span><b>${Number(stats.visitsMonth || 0).toLocaleString("ar-SA")}</b></article><article><span>إجمالي الزيارات</span><b>${Number(stats.visits || 0).toLocaleString("ar-SA")}</b></article></section><section class="analytics-grid"><article class="analytics-card analytics-wide"><h3>حركة الزيارات — آخر 7 أيام</h3><div class="analytics-bars">${bars}</div></article><article class="analytics-card"><h3>مصادر الزيارة</h3><ul class="analytics-list">${sourceRows}</ul></article><article class="analytics-card"><h3>أنواع الأجهزة</h3><ul class="analytics-list">${deviceRows}</ul></article><article class="analytics-card"><h3>حالات الطلبات</h3><ul class="analytics-list">${requestRows}</ul></article><article class="analytics-card"><h3>أكثر الخدمات مشاهدة</h3><ul class="analytics-list">${serviceRows}</ul></article><article class="analytics-card"><h3>أكثر المقالات مشاهدة</h3><ul class="analytics-list">${articleRows}</ul></article><article class="analytics-card"><h3>أكثر الملفات تحميلاً</h3><ul class="analytics-list">${downloadRows}</ul></article></section>`; }
function latestRecordsPanels(stats) { const groups = [["آخر الطلبات", stats.recentRequests, "requests", item => `#${item.id} — ${item.studentName}`], ["آخر الرسائل", stats.recentMessages, "messages", item => item.subject || item.name], ["آخر التقييمات", stats.recentReviews, "submittedReviews", item => item.name], ["آخر الملفات", stats.recentMedia, "gallery", item => item.originalName], ["آخر المقالات", stats.recentArticles, "articles", item => item.title || "مقال دون عنوان"]]; return `<section class="recent-records"><div class="section-heading"><div><p class="eyebrow">آخر المستجدات</p><h3>السجلات والمحتوى</h3></div></div><div class="recent-grid">${groups.map(([title, entries, target, label]) => { const safeEntries = Array.isArray(entries) ? entries.slice(0, 4) : []; return `<article class="recent-card"><div class="recent-card-head"><h4>${title}</h4><button class="btn btn-outline btn-small" data-select="${target}">عرض</button></div>${safeEntries.length ? `<ul>${safeEntries.map(item => `<li><span>${esc(String(label(item)))}</span><small>${item.createdAt ? fmtDate(item.createdAt) : (title === "آخر المقالات" ? esc(String(item.publishedText || "دون تاريخ نشر")) : "محتوى الموقع")}</small></li>`).join("")}</ul>` : `<p>لا توجد بيانات بعد.</p>`}</article>`; }).join("")}</div></section>`; }
function dashboardWorkspace() { const s = state.stats || {}; const activities = s.activities || []; const alerts = [{ label: "رسائل جديدة", count: s.messages, target: "messages", icon: "✉" }, { label: "تقييمات بانتظار المراجعة", count: s.pendingReviews, target: "submittedReviews", icon: "★" }, { label: "طلبات تحتاج المتابعة", count: s.requests, target: "requests", icon: "▣" }].filter(item => Number(item.count || 0) > 0); return `<section class="workspace dashboard-workspace"><div class="workspace-head"><div><p class="eyebrow">مركز المتابعة</p><h2>نظرة عامة على الأعمال</h2><p>تابع الطلبات والرسائل والمحتوى من مكان واحد.</p></div><div class="head-actions"><button class="btn btn-outline btn-small" data-download-backup>تنزيل نسخة احتياطية</button><button class="btn btn-small" data-select="requests">عرض الطلبات</button></div></div><div class="workspace-body"><section class="action-banner"><div><span class="action-banner-icon">⚡</span><div><b>جاهز لإدارة يومك</b><p>الحفظ مباشر وآمن في قاعدة البيانات.</p></div></div><button class="btn btn-soft btn-small" data-select="siteSettings">إعدادات الموقع</button></section>${alerts.length ? `<section class="alert-panel"><div class="alert-panel-title"><span>🔔</span><div><b>تحتاج إلى متابعة</b><small>عناصر تم رصدها في لوحة الإدارة</small></div></div><div class="alert-actions">${alerts.map(item => `<button class="alert-action" data-select="${item.target}"><span>${item.icon}</span><b>${Number(item.count)}</b><small>${esc(item.label)}</small></button>`).join("")}</div></section>` : `<div class="notice notice-success"><b>لا توجد عناصر جديدة.</b> لوحة المتابعة هادئة الآن ويمكنك إدارة المحتوى وقتما تشاء.</div>`}${latestRecordsPanels(s)}${analyticsPanel(s)}<section class="activity-section"><div class="section-heading"><div><p class="eyebrow">سجل الإدارة</p><h3>آخر النشاطات</h3></div></div><div class="item-list">${activities.length ? activities.map(item => `<article class="item-row activity-row"><div class="item-title"><span class="activity-icon">◷</span><div><b>${esc(item.action)}</b><br><small>${esc(item.entityType)} — ${fmtDate(item.createdAt)}</small></div></div></article>`).join("") : `<div class="empty">لا توجد أنشطة إدارية مسجلة بعد.</div>`}</div></section></div></section>`; }
function serviceEditor(item, index) { return `<div class="editor" data-editor="${index}"><div class="editor-head"><h3>تحرير الخدمة والخدمات الفرعية</h3><button class="btn btn-outline btn-small" data-cancel>إغلاق</button></div><div class="two-col"><div class="field"><label>الرمز</label><input data-service-prop="emoji" value="${esc(item.emoji || "📚")}" /></div><div class="field"><label>اسم الخدمة</label><input data-service-prop="title" value="${esc(item.title || "")}" /></div></div><div class="field"><label>الخدمات الفرعية (خدمة واحدة في كل سطر)</label><textarea data-service-prop="items">${esc((item.items || []).join("\n"))}</textarea></div><button class="btn btn-small" data-save-service="${index}">حفظ الخدمة</button></div>`; }
function genericEditor(item, index) { return `<div class="editor" data-editor="${index}"><div class="editor-head"><h3>تحرير العنصر</h3><button class="btn btn-outline btn-small" data-cancel>إغلاق</button></div><div class="field"><label>بيانات العنصر</label><textarea data-json-editor="${index}" dir="ltr">${esc(JSON.stringify(item, null, 2))}</textarea></div><button class="btn btn-small" data-save-json="${index}">حفظ العنصر</button></div>`; }
function settingsEditor(data) { const clean = sanitizeSettings(data); return `<div class="editor"><div class="notice">تنعكس تعديلات الشعار وبيانات التواصل والإعلان وبيانات SEO على الموقع العام دون إظهار لوحة الإدارة للزوار.</div><div class="field"><label>رفع صورة جديدة للشعار (PNG/JPG/WebP، حتى 3 ميغابايت)</label><input id="logo-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml" /><button type="button" class="btn btn-soft btn-small" data-upload-logo>رفع الصورة وتحديث رابط الشعار</button></div>${Object.entries(clean).map(([key, value]) => `<div class="field"><label>${esc(settingLabels[key] || key)}</label>${String(value).length > 70 ? `<textarea data-setting="${key}">${esc(value)}</textarea>` : `<input data-setting="${key}" value="${esc(value)}" />`}</div>`).join("")}<button class="btn" data-save-settings>حفظ إعدادات الموقع</button></div>`; }
function mountCompatibleDownloadsManager() {
  const manager = window.WajbatDownloadsManager;
  if (state.selected !== "downloads" || typeof manager?.activate !== "function") return null;
  queueMicrotask(() => {
    if (!document.querySelector("[data-downloads-workspace]") || state.selected !== "downloads") return;
    try { manager.activate(); } catch (error) { toast(messageOf(error)); }
  });
  return `<section class="workspace side-workspace" data-downloads-workspace><div class="workspace-body"></div></section>`;
}
function mountCompatibleVisitorLinksManager() {
  const manager = window.WajbatVisitorLinksManager;
  if (state.selected !== "visitorLinks" || typeof manager?.workspace !== "function" || typeof manager?.activate !== "function") return null;
  queueMicrotask(() => {
    if (!document.querySelector("[data-visitor-links-workspace]") || state.selected !== "visitorLinks") return;
    void manager.activate();
  });
  return `<section class="workspace" data-visitor-links-workspace><div class="workspace-body"></div></section>`;
}
function contentWorkspace() { const key = state.selected; const [icon, title, description] = labels[key]; const data = content(key); if (key === "services" && window.WajbatServicesManager) return window.WajbatServicesManager.workspace(data); if (key === "visitorLinks") { const managerWorkspace = mountCompatibleVisitorLinksManager(); if (managerWorkspace) return managerWorkspace; } if (key === "downloads") { const managerWorkspace = mountCompatibleDownloadsManager(); if (managerWorkspace) return managerWorkspace; } if (key === "siteSettings") return `<section class="workspace"><div class="workspace-head"><div><h2>${icon} ${title}</h2><p>${description}</p></div></div><div class="workspace-body">${settingsEditor(data)}</div></section>`; const items = Array.isArray(data) ? data : []; const rows = items.map((item, index) => `<article class="item-row"><div class="item-title"><span>${esc(item.emoji || icon)}</span><div><b>${esc(labelForItem(item, index))}</b><br><small>${key === "services" ? `${(item.items || []).length} خدمات فرعية` : (item.category || item.university || item.kind || "")}</small></div><span class="status ${item.isVisible === false ? "hidden" : ""}">${item.isVisible === false ? "مخفي" : "ظاهر"}</span></div><div class="row-actions"><button class="btn btn-outline btn-small" data-move="${index}:up">↑</button><button class="btn btn-outline btn-small" data-move="${index}:down">↓</button><button class="btn btn-soft btn-small" data-edit="${index}">تعديل</button><button class="btn btn-soft btn-small" data-toggle="${index}">${item.isVisible === false ? "إظهار" : "إخفاء"}</button><button class="btn btn-danger btn-small" data-delete="${index}">حذف</button></div></article>${state.editing === index ? (key === "services" ? serviceEditor(item, index) : genericEditor(item, index)) : ""}`).join(""); return `<section class="workspace"><div class="workspace-head"><div><h2>${icon} ${title}</h2><p>${description} — أضف، عدّل، احذف، أظهر أو أخفِ، وغيّر الترتيب.</p></div><button class="btn btn-small" data-add>+ إضافة</button></div><div class="workspace-body">${rows ? `<div class="item-list">${rows}</div>` : `<div class="empty">لا توجد عناصر في هذا القسم.</div>`}</div></section>`; }
function requestsWorkspace() { const visible = state.requests.filter(item => (!state.requestSearch || [item.studentName, item.university, item.course, item.serviceType].some(value => String(value || "").toLowerCase().includes(state.requestSearch.toLowerCase()))) && (!state.requestStatus || item.status === state.requestStatus)); return `<section class="workspace"><div class="workspace-head"><div><h2>📋 طلبات العملاء</h2><p>ابحث في الطلبات، صفِّها، حدّث الحالة، وأضف ملاحظات داخلية.</p></div><button class="btn btn-outline btn-small" data-export-requests>تصدير CSV</button></div><div class="workspace-body"><div class="two-col"><div class="field"><label>بحث</label><input data-request-search value="${esc(state.requestSearch)}" placeholder="اسم الطالب أو الجامعة أو المقرر" /></div><div class="field"><label>تصفية الحالة</label><select data-request-filter><option value="">كل الحالات</option>${statusOptions(state.requestStatus, ["new", "reviewing", "in_progress", "completed", "cancelled"])}</select></div></div><div class="item-list">${visible.length ? visible.map(item => `<article class="editor"><div class="editor-head"><div><h3>#${item.id} — ${esc(item.studentName)}</h3><small>${esc(item.university)} · ${esc(item.course)} · ${fmtDate(item.createdAt)}</small></div><span class="status">${statuses[item.status] || item.status}</span></div><div class="notice"><b>${esc(item.serviceType)}</b> — الموعد: ${esc(item.deadline)}<br>${esc(item.description)}${item.attachmentMediaId ? "<br><small>مرفق محفوظ في مكتبة الملفات.</small>" : ""}</div><div class="two-col"><div class="field"><label>الحالة</label><select data-request-status="${item.id}">${statusOptions(item.status, ["new", "reviewing", "in_progress", "completed", "cancelled"])}</select></div><div class="field"><label>ملاحظات داخلية</label><textarea data-request-notes="${item.id}">${esc(item.adminNotes || "")}</textarea></div></div><button class="btn btn-small" data-save-request="${item.id}">حفظ التحديث</button></article>`).join("") : `<div class="empty">لا توجد طلبات مطابقة للبحث أو التصفية.</div>`}</div></div></section>`; }
function messagesWorkspace() { const visible = state.messages.filter(item => (!state.messageSearch || [item.name, item.subject, item.phone, item.email].some(value => String(value || "").toLowerCase().includes(state.messageSearch.toLowerCase()))) && (!state.messageStatus || item.status === state.messageStatus)); return `<section class="workspace"><div class="workspace-head"><div><h2>✉ رسائل التواصل</h2><p>ابحث في استفسارات الزوار وصفِّها وسجّل حالة الرد والملاحظات.</p></div></div><div class="workspace-body"><div class="two-col"><div class="field"><label>بحث</label><input data-message-search value="${esc(state.messageSearch)}" placeholder="الاسم أو الموضوع أو الجوال" /></div><div class="field"><label>تصفية الحالة</label><select data-message-filter><option value="">كل الحالات</option>${statusOptions(state.messageStatus, ["new", "read", "replied", "archived"])}</select></div></div><div class="item-list">${visible.length ? visible.map(item => `<article class="editor"><div class="editor-head"><div><h3>${esc(item.subject)} — ${esc(item.name)}</h3><small>${esc(item.phone)}${item.email ? ` · ${esc(item.email)}` : ""} · ${fmtDate(item.createdAt)}</small></div><span class="status">${statuses[item.status] || item.status}</span></div><div class="notice">${esc(item.message)}</div><div class="two-col"><div class="field"><label>الحالة</label><select data-message-status="${item.id}">${statusOptions(item.status, ["new", "read", "replied", "archived"])}</select></div><div class="field"><label>ملاحظات داخلية</label><textarea data-message-notes="${item.id}">${esc(item.adminNotes || "")}</textarea></div></div><button class="btn btn-small" data-save-message="${item.id}">حفظ التحديث</button></article>`).join("") : `<div class="empty">لا توجد رسائل مطابقة للبحث أو التصفية.</div>`}</div></div></section>`; }
function submittedReviewsWorkspace() { return `<section class="workspace"><div class="workspace-head"><div><h2>★ تقييمات بانتظار المراجعة</h2><p>لا تُعرض التقييمات الجديدة للزوار قبل اعتمادها يدوياً.</p></div></div><div class="workspace-body"><div class="item-list">${state.submittedReviews.length ? state.submittedReviews.map(item => `<article class="item-row"><div class="item-title"><span>★</span><div><b>${esc(item.name)} — ${esc(item.university)}</b><br><small>${esc(item.review)} · ${fmtDate(item.createdAt)}</small></div><span class="status">${statuses[item.status] || item.status}</span></div><div class="row-actions"><button class="btn btn-small" data-review-status="${item.id}:published">نشر</button><button class="btn btn-soft btn-small" data-review-status="${item.id}:hidden">إخفاء</button><button class="btn btn-danger btn-small" data-delete-review="${item.id}">حذف</button></div></article>`).join("") : `<div class="empty">لا توجد تقييمات جديدة.</div>`}</div></div></section>`; }
function mediaWorkspace() { return `<section class="workspace"><div class="workspace-head"><div><h2>▧ معرض الصور والوسائط</h2><p>ارفع الصور والملفات بصيغ مسموحة واربطها بالمحتوى أو بالطلبات دون إدخال روابط.</p></div></div><div class="workspace-body"><form data-media-upload class="editor"><div class="field"><label>اختر صورة أو ملفاً من جهازك</label><input name="media" type="file" required accept="image/jpeg,image/png,image/webp,image/gif,image/svg+xml,application/pdf,.doc,.docx" /></div><div class="field"><label>استخدام الوسيط</label><input name="usage" placeholder="مثال: شعار الموقع أو تحميلات" /></div><button class="btn" type="submit">رفع إلى المعرض</button></form><div class="item-list">${state.media.length ? state.media.map(item => `<article class="item-row" data-media-category="${item.category === "image" ? "image" : "file"}"><div class="item-title"><span>${item.category === "image" ? "▧" : "▤"}</span><div><b>${esc(item.originalName)}</b><br><small>${esc(item.mimeType)} · ${Math.round(item.sizeBytes / 1024)} كيلوبايت · ${fmtDate(item.createdAt)}</small></div></div><div class="row-actions"><a class="btn btn-outline btn-small" href="${esc(item.url)}" target="_blank" rel="noopener">فتح</a><button class="btn btn-danger btn-small" data-delete-media="${item.id}">حذف</button></div></article>`).join("") : `<div class="empty">لا توجد وسائط مرفوعة حالياً.</div>`}</div></div></section>`; }
