function workspace() { if (state.selected === "dashboard") return dashboardWorkspace(); if (state.selected === "analytics") return analyticsWorkspace(); if (state.selected === "requests") return requestsWorkspace(); if (state.selected === "messages") return messagesWorkspace(); if (state.selected === "submittedReviews") return submittedReviewsWorkspace(); if (state.selected === "gallery") return mediaWorkspace(); if (state.selected === "ownerLogin") return ownerLoginWorkspace(); if (state.selected === "account") return accountWorkspace(); return contentWorkspace(); }
function openVisitorLinksWorkspace(event) { const button = event.currentTarget ?? event.target.closest?.("[data-visitor-links-nav]"); if (!button) return; event.preventDefault(); event.stopPropagation(); state.selected = "visitorLinks"; state.editing = null; state.navOpen = false; dashboard(); }
