function ownerLoginFormValues(form) { const next = { ...loginDefaults(), ...(state.ownerLoginSettings || {}) }; for (const [name, raw] of new FormData(form).entries()) { if (typeof raw !== "string") continue; if (["backgroundImageMediaId", "logoMediaId", "ownerPhotoMediaId"].includes(name)) { next[name] = raw ? Number(raw) : null; continue; } if (["logoSize", "ownerPhotoSize", "cardOpacity", "cardRadius", "cardBlur", "cardWidth", "fieldFontSize", "buttonRadius"].includes(name)) { next[name] = Number(raw); continue; } next[name] = raw; } const mediaById = id => state.media.find(item => Number(item.id) === Number(id)); next.backgroundImageUrl = mediaById(next.backgroundImageMediaId)?.url || null; next.logoUrl = mediaById(next.logoMediaId)?.url || null; next.ownerPhotoUrl = mediaById(next.ownerPhotoMediaId)?.url || null; return next; }
