async function uploadOwnerLoginImage(input) { const file = input.files?.[0]; if (!file) return; if (!file.type.startsWith("image/")) throw new Error("اختر ملف صورة صالحاً فقط"); if (file.size > 3 * 1024 * 1024) throw new Error("يجب ألا تتجاوز الصورة 3 ميغابايت"); const kind = input.dataset.ownerLoginUpload; const result = await mutate("admin.uploadMedia", { mimeType: file.type, dataUrl: await fileToDataUrl(file), originalName: file.name, usage: kind === "logo" ? "شعار شاشة دخول المالك" : kind === "ownerPhoto" ? "صورة مالك شاشة الدخول" : "خلفية شاشة دخول المالك" }); await refresh(); state.selected = "ownerLogin"; dashboard(); const target = document.querySelector(`[data-owner-login-settings] input[type="hidden"][name="${kind}MediaId"]`); if (target) { target.value = String(result.id); renderOwnerLoginPreview(ownerLoginFormValues(target.closest("form"))); } toast("تم رفع الصورة وربطها بالمسودة. اضغط حفظ لاعتمادها في شاشة الدخول."); }
