function normalizeLoginEmail(value) { return value.trim().replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g, ""); }
async function submitLogin(event) { event.preventDefault(); const form = event.currentTarget; const errorBox = form.querySelector("#login-error"); errorBox.textContent = ""; const email = normalizeLoginEmail(form.email.value); const password = form.password.value; if (!email || !password) { errorBox.textContent = "أدخل البريد الإلكتروني وكلمة المرور."; return; } try { await mutate("adminAuth.login", { email, password }); await refresh(); } catch (error) { errorBox.textContent = state.loginSettings?.invalidCredentialsText || messageOf(error); } }
