document.addEventListener("submit", event => { const form = event.target; if (form.matches("form[data-backup-restore]")) { event.preventDefault(); const file = form.elements.backup.files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) return toast("يجب ألا يتجاوز ملف النسخة 5 ميغابايت"); if (!window.confirm("سيتم استبدال المحتوى المدَار. هل تريد المتابعة؟")) return; void file.text().then(JSON.parse).then(backup => mutate("admin.restoreContentBackup", { backup })).then(result => refresh().then(() => toast(`تم استيراد ${result.restoredCollections} مجموعات محتوى`))).catch(error => toast(messageOf(error))); return; } if (form.matches("form[data-media-upload]")) { event.preventDefault(); const file = form.elements.media.files?.[0]; if (!file) return; void (async () => { await mutate("admin.uploadMedia", { mimeType: file.type, dataUrl: await fileToDataUrl(file), originalName: file.name, usage: form.elements.usage.value }); await refresh(); toast("تم رفع الملف إلى المكتبة"); })().catch(error => toast(messageOf(error))); } if (form.matches("form[data-account-form]")) { event.preventDefault(); const data = new FormData(form); void mutate("adminAuth.updateCredentials", { currentPassword: data.get("currentPassword"), email: data.get("email") || undefined, newPassword: data.get("newPassword") || undefined }).then(() => { toast("تم حفظ بيانات الحساب. سجّل الدخول من جديد."); document.querySelector("#admin-root").innerHTML = loginView(); bindLoginForm(); }).catch(error => toast(messageOf(error))); } });
