async function boot() {
  const root = document.querySelector("#admin-root");
  root.innerHTML = `<div class="loading">جارٍ التحقق من صلاحية الوصول…</div>`;
  try {
    state.loginSettings = await query("adminAuth.loginSettings");
  } catch {
    state.loginSettings = null;
  }
  try {
    // لا نبدأ تسع طلبات محمية قبل معرفة حالة الجلسة. هذا يجعل نموذج الدخول
    // يظهر مباشرة عند غياب الجلسة بدلاً من بقائه في حالة التحميل.
    state.account = await query("adminAuth.account");
    await refresh();
  } catch {
    root.innerHTML = loginView();
    bindLoginForm();
  }
}
